message:
${set attacker sender}
${set defender username 1}
${set self same attacker defender}

${set attackerRating stat attacker rating 1000}
${set defenderRating stat defender rating 1000}
${set attackerStreak stat attacker streak}
${set defenderStreak stat defender streak}

${set roll random 1 20}

${set difficulty 16}
${set pressure attackerStreak}
${limit pressure 0 2}
${add difficulty pressure}
${set comeback 0 - attackerStreak}
${limit comeback 0 3}
${subtract difficulty comeback}
${set ratingGap (defenderRating - attackerRating) / 150}
${round ratingGap}
${limit ratingGap -2 2}
${add difficulty ratingGap}
${limit difficulty 10 19}
${set chance (21 - difficulty) * 5}

${set won roll >= difficulty}
${if roll == 1}${set won 0}${end}
${if roll == 20}${set won 1}${end}
${if won == 1}
  ${set winner attacker}${set loser defender}
${else}
  ${set winner defender}${set loser attacker}
${end}

${if self == 0}
${set winnerChance chance}
${set margin roll - difficulty}
${if won == 0}
  ${set winnerChance 100 - chance}
  ${set margin difficulty - roll - 1}
${end}
${limit margin 0 5}
${set xpAward 10 + (100 - winnerChance) * 2 / 5 + margin}
${set xpLoss 2 + (100 - winnerChance) / 5 + margin / 2}
${if roll == 1 || roll == 20}
  ${add xpAward 5}
  ${add xpLoss 3}
${end}
${round xpAward}
${round xpLoss}
${set loserXP stat loser xp}
${if xpLoss > loserXP}${set xpLoss loserXP}${end}
${set xpDebit 0 - xpLoss}
${addstat winner wins 1}
${addstat loser losses 1}
${addstat winner xp xpAward}
${addstat loser xp xpDebit}
${end}

${if self == 0}
${if won == 1}
  ${limit attackerStreak 0 1000000}${add attackerStreak 1}
  ${limit defenderStreak -1000000 0}${subtract defenderStreak 1}
${else}
  ${limit attackerStreak -1000000 0}${subtract attackerStreak 1}
  ${limit defenderStreak 0 1000000}${add defenderStreak 1}
${end}
${setstat attacker streak attackerStreak}
${setstat defender streak defenderStreak}
${end}

${if self == 0}
${set ratingChange (won - chance / 100) * 24}
${round ratingChange}
${add attackerRating ratingChange}
${subtract defenderRating ratingChange}
${limit attackerRating 800 2000}
${limit defenderRating 800 2000}
${setstat attacker rating attackerRating}
${setstat defender rating defenderRating}
${end}

 ${attacker} challenges ${defender}! ${if self == 1}Mirror match: exhibition rules.${else}Roll for initiative!${end} 

 • NEED: ${difficulty}+ on a D20 (${chance}% chance). • ROLLED: ${attacker} rolled ${roll}/20. • ${if roll == 1}CRITICAL FAILURE!${else}${if roll == 20}CRITICAL SUCCESS!${else}${if won == 1}SUCCESS!${else}FAILED!${end}${end}${end} 

 ${if self == 1}${random.pick "${attacker} hurt themself in their confusion! It was super embarrassing." "${attacker} challenged their reflection. The mirror filed a restraining order." "${attacker} got their ass kicked by their shadow. A flawless demonstration of clownery." "${attacker} rolled initiative against their last brain cell. The brain cell fled." "${attacker} cast Fireball at their feet. The dungeon master needs a drink." "${attacker} used Self-Destruct! The audience politely stepped back. Death" "${attacker} tried to parry an intrusive thought and punched their own face." "${attacker} fought their inner demons. The demons asked for a different party." "${attacker} defeated their trousers. Please close the curtains, you menace." "${attacker} failed a wisdom save against a revolving door."} No XP, wins, losses or rating changes.${end} 

 ${if self == 0}${if roll == 1}${random.pick "${attacker} trips over a banana and critically fails to remain upright. Death" "${attacker} rolls to intimidate a chair. The chair wins." "${attacker} swings so hard their weapon joins another adventuring party." "${attacker} casts a spell with the microphone muted. Nothing happens." "${attacker} mistakes the mimic for a loot chest. The loot bites back." "${attacker} fails the tutorial. Even the goblins look concerned."}${end}${end} 

 ${if self == 0}${if roll == 20}${random.pick "${attacker} lands a legendary finishing blow. The bard is already writing the song. Death" "${attacker} used Hyper Beam! It was super effective!" "${attacker} parries fate itself and lands the final strike." "${attacker} summons a spectral goose. Peace was never an option." "${attacker} lands a sneak attack in broad daylight. Nobody questions it." "${attacker} wins so decisively the dungeon master checks the dice."}${end}${end} 

 ${if self == 0 && roll > 1 && roll < 20}${if won == 1}${random.pick "${attacker} breaks through the guard with a perfectly timed counterattack!" "${attacker} lands the winning strike. Loot goblin instincts immediately activate." "${attacker} wins the skill check. The party erupts into questionable applause." "${attacker} dodges, feints and sends their opponent back to the tavern." "${attacker} rolls through the attack. Somewhere, a bonfire has been lit." "${attacker} wins! The quest log updates: act surprised."}${else}${if roll == difficulty - 1}${random.pick "${defender} dodges by one hit point, then lands the winning counterattack!" "${attacker} misses by a whisker. The dice demand a sacrifice." "${defender} passes the saving throw with a suspiciously smug grin." "${attacker} almost lands the combo, then presses the wrong key." "${defender} wins the duel by the width of a goblin toenail." "${attacker} needed just one more point. The bard plays a tiny violin."}${else}${random.pick "${defender} parries and wins the duel. The healer refuses responsibility." "${attacker} attacks the tank and discovers why that was a bad idea." "${defender} counters with Vicious Mockery. Emotional damage!" "${attacker} drinks a potion labelled probably fine. It was not fine." "${defender} wins the encounter. The respawn screen offers unsolicited advice." "${attacker} loses the duel but insists it was lag."}${end}${end}${end} 

 ${if self == 0}• RESULT: ${winner} wins (+${xpAward} XP); ${loser} loses (-${xpLoss} XP).${end}

